-- Ribbon TERRAIN as REAL noise-driven map-gen (§4, §15-2; ci-3yl, rewritten for
-- the per-zone gradient in ci-a35).
--
-- The ribbon is generated by the MAP-GEN itself, not by an on_chunk_generated
-- script. This module turns the pure per-zone layout (scripts/zones.lua) into the
-- concrete map-gen artefacts: the Cindra-exclusive tile PROTOTYPES (consumed at
-- the data stage by prototypes/tiles.lua) and, for each, a Factorio NOISE
-- EXPRESSION that places it in its band. The engine picks, per tile, the
-- candidate with the highest `probability_expression`, so the bands arrange
-- themselves; a smooth shared `basis_noise` term is added to the perpendicular
-- coordinate so every band boundary is an ORGANIC wavy curve, never a straight
-- line.
--
-- Gradient, HOT (sunward) edge inward to the COLD (nightward) edge (scripts/zones):
--
--   hot-lava | lava | cracks-hot || cracks-warm | cracks-plain | jagged | dirt |
--   SAND (spawn) | aquilo-dust (varied) | rough-ice | ==ICE CLIFF== | smooth-ice
--
-- The three hottest bands deal FIRE damage (ramping, hottest at hot-lava) and
-- smooth-ice deals FREEZE damage; everything between is safe (scripts/tile-damage
-- reads M.lethal_tiles / M.fire_intensity). The world is finite PERPENDICULAR via
-- the map-gen's own `width` = the SUM of every zone width (M.finite_dimension);
-- the engine voids everything beyond +/- sum/2 with `out-of-map`.
--
-- PURE where it counts: the *_expr emitters, lethal_kind and geometry are plain
-- string/number logic (no game.* / prototypes.*), so the bands are unit-testable
-- off the game (unit-tests/test_terrain.lua). The clone-source table is consumed
-- only at the data stage (prototypes/tiles.lua). Boundaries read the SAME zone
-- layout as scripts/ribbon.lua's axis, so the VISIBLE terrain and the FELT damage
-- share one source of truth.

local zones = require("scripts.zones")
local axis = require("scripts.axis")

local M = {}

-- Smooth-noise amplitude (tiles) and wavelength (tiles) that wiggles every band
-- boundary so the bands are organic, never straight. Fixed seeds -> the ribbon
-- has the same band structure on every map seed (a ribbon world is a fixed shape,
-- not a per-seed lottery), and it stays deterministic for tests. (tune)
M.NOISE_AMPLITUDE = 7
M.NOISE_WAVELENGTH = 48

-- A large constant baseline added to every band's probability so the WINNING band
-- is always positive (the engine has no default tile; one candidate must always
-- win). Being the same constant for every band, it never changes which band wins.
M.BASE = 10000

-- Within a VARIED band (Aquilo dust), how strongly the per-variant selector noise
-- swings, and its pitch (tiles). Small, so variants patch inside the band without
-- bleeding materially past its boundaries. (tune)
M.VARIETY_AMPLITUDE = 2
M.VARIETY_WAVELENGTH = 12

-- Format a number for the noise DSL (integers stay clean, no float noise).
local function num(v)
  if v == math.floor(v) then return string.format("%d", v) end
  return string.format("%.6g", v)
end

-- A smooth basis-noise term ~+/-amp tiles at ~wl pitch. `seed1` varies the field.
local function noise(seed1, amp, wl)
  return "basis_noise{x = x, y = y, seed0 = 1, seed1 = " .. num(seed1) ..
         ", input_scale = " .. num(1 / wl) ..
         ", output_scale = " .. num(amp) .. "}"
end

-- The perpendicular coordinate (sunward-positive; scripts/axis owns the
-- orientation) perturbed by ONE shared wiggle field, so adjacent band boundaries
-- share the exact same organic crossing (no gaps, no overlaps).
local function perp_wiggled()
  return "(" .. axis.perp_expr() .. " + " .. noise(11, M.NOISE_AMPLITUDE, M.NOISE_WAVELENGTH) .. ")"
end

-- The tile list, decorated with each tile's zone + variant, built once from the
-- zone layout. Non-varied zones contribute one tile; a VARIED zone (Aquilo dust)
-- contributes several `-N` variants cloned from different vanilla dust tiles.
-- `index_from` (a[cindra]-...) preserves the hot->cold order for Factoriopedia.
local function build_tiles()
  local list = {}
  local L = zones.layout()
  for zi, z in ipairs(L.zones) do
    if z.varied then
      for vi, src in ipairs(z.clone_from) do
        list[#list + 1] = {
          name = z.tile .. "-" .. vi, clone_from = src,
          zone = z, variant = vi, order_key = zi,
        }
      end
    else
      list[#list + 1] = {
        name = z.tile, clone_from = z.clone_from,
        zone = z, variant = nil, order_key = zi,
      }
    end
  end
  return list
end

M.TILES = build_tiles()

-- name -> tile record, for the per-name emitters/lookups below.
local BY_NAME = {}
for _, t in ipairs(M.TILES) do BY_NAME[t.name] = t end

-- The `probability_expression` string for a Cindra tile. Each band is a "tent":
-- min(perp - lo, hi - perp) is POSITIVE only inside [lo, hi] (peaking mid-band)
-- and negative outside, so the band whose range contains a point uniquely wins;
-- beyond the outermost bands (which reach the void edge) the least-negative tent
-- still wins, guaranteeing full coverage. A VARIED band adds a small per-variant
-- selector noise so its variants patch within the band.
function M.probability_expr(name)
  local t = BY_NAME[name]
  if not t then error("terrain: unknown Cindra tile " .. tostring(name)) end
  local z = t.zone
  local pw = perp_wiggled()
  local tent = "min(" .. pw .. " - " .. num(z.lo_p) .. ", " .. num(z.hi_p) .. " - " .. pw .. ")"
  local expr = num(M.BASE) .. " + (" .. tent .. ")"
  if t.variant then
    -- distinct seed per variant so they never coincide; small amplitude.
    expr = expr .. " + " .. noise(200 + t.variant, M.VARIETY_AMPLITUDE, M.VARIETY_WAVELENGTH)
  end
  return expr
end

-- "heat" / "cold" / nil: the damage kind a lethal tile inflicts (nil = safe).
-- Fire bands map to "heat", the freeze band to "cold" (the concrete damage-type
-- prototypes, prototypes/damage-types.lua). scripts/tile-damage.lua reads this.
function M.lethal_kind(name)
  local t = BY_NAME[name]
  if not t then return nil end
  local d = t.zone.damage
  if d == "fire" then return "heat" end
  if d == "freeze" then return "cold" end
  return nil
end

-- The set of every lethal tile name -> its damage kind (built once).
function M.lethal_tiles()
  local out = {}
  for _, t in ipairs(M.TILES) do
    local k = M.lethal_kind(t.name)
    if k then out[t.name] = k end
  end
  return out
end

-- Relative damage magnitude (0..1) for a lethal tile: ramps the FIRE band so the
-- hot-lava edge bites hardest and cracks-hot is a gentler singe; the freeze band
-- is full. Safe tiles return 0. scripts/tile-damage multiplies this by max-dps.
function M.fire_intensity(name)
  local t = BY_NAME[name]
  if not t or not t.zone.damage then return 0 end
  return t.zone.intensity or 1.0
end

-- All Cindra tile names (for the map-gen autoplace_settings.tile allow-list).
function M.tile_names()
  local out = {}
  for _, t in ipairs(M.TILES) do out[#out + 1] = t.name end
  return out
end

-- The FINITE map dimension (tiles) that bounds the ribbon perpendicular to its
-- long axis: the SUM of every zone width (ci-a35). The engine voids everything
-- beyond +/- dim/2, so the ribbon is finite perpendicular straight from the
-- map-gen. Vertical ribbon -> bound X (`width`); horizontal -> bound Y (`height`).
function M.finite_dimension()
  return {
    key = (axis.orientation() == axis.HORIZONTAL) and "height" or "width",
    value = zones.layout().total,
  }
end

-- The world spawn: the centre of the SAND band. Because the band is geometric-
-- centred but the hot side is wider, the sand centre sits OFF the world origin;
-- scripts/driver.lua moves the force spawn here so a fresh landing is on the wide
-- safe sand. Returns a {x, y} on the long (ribbon) axis at y/x = 0.
function M.spawn_position()
  local ref = zones.layout().ref            -- sand centre, perpendicular coordinate
  if axis.orientation() == axis.HORIZONTAL then
    -- horizontal: perp = y (sunward +y), long axis = x. spawn perp = ref.
    return { x = 0, y = ref }
  end
  -- vertical (default): perp = -x, long axis = y. sand-centre x = -ref.
  return { x = -ref, y = 0 }
end

-- The ice-cliff wall: the perpendicular coordinate of the rough-ice / smooth-ice
-- boundary, as a `cliff_elevation` noise expression whose single in-map contour
-- runs continuously along that line (prototypes/noise.lua + prototypes/planet.lua
-- turn this into an impassable ice cliff). Returns the boundary coordinate and a
-- ramp expression that increases across the perpendicular axis.
function M.cliff_boundary()
  return zones.layout().cliff_p
end

-- A `cliff_elevation` expression: a linear ramp in the perpendicular axis, offset
-- so ONE contour lands exactly on the rough/smooth boundary. The map-gen's
-- cliff_settings (interval bigger than the map) then makes that the only cliff
-- line, running continuously along the ribbon's long axis.
function M.cliff_elevation_expr()
  -- perp increases sunward; the boundary is at perp = cliff_p (a negative,
  -- nightward value). Ramp value 0 exactly on the boundary.
  return "(" .. axis.perp_expr() .. " - (" .. num(M.cliff_boundary()) .. "))"
end

return M
